// n8n Code node (JavaScript) — collect IDs of tickets tagged "sales_ticket"
// Input: items from a Zendesk "Get many tickets" or Search node
// Output: ONE item => { sales_tickets: ["22629954", "22628420", ...] }

const TARGET_TAG = 'sales_ticket';
const out = new Set();

// Helper: normalize any "tags" field to an array of strings
function normalizeTags(tags) {
  if (Array.isArray(tags)) return tags.map(String);
  if (typeof tags === 'string') {
    // accept comma/space separated strings
    return tags.split(/[, ]+/).map(s => s.trim()).filter(Boolean);
  }
  return [];
}

// Gather candidate ticket objects from various possible shapes
for (const item of items) {
  const j = item?.json ?? {};

  // Case A: ticket is directly in item.json
  if (j && (j.id !== undefined || j.tags !== undefined)) {
    const tags = normalizeTags(j.tags);
    if (tags.includes(TARGET_TAG) && j.id != null) out.add(String(j.id));
  }

  // Case B: Zendesk Search responses nested at json.body.results
  const results = j?.body?.results;
  if (Array.isArray(results)) {
    for (const t of results) {
      const tags = normalizeTags(t?.tags);
      if (tags.includes(TARGET_TAG) && t?.id != null) out.add(String(t.id));
    }
  }
}

// Return a single item with the array of strings (may be empty)
return [
  {
    json: {
      sales_tickets: Array.from(out),
    },
  },
];

